#include <stdio.h>

#include <stdlib.h>

struct node {
int data;
struct node * next;
};

struct node * head = NULL;

// Create Circular Linked List
void create() {
int val;
struct node * temp, * newnode;

printf("Enter zero to stop: ");
while (1) {
scanf("%d", & val);
if (val == 0)
break;

newnode = (struct node * ) malloc(sizeof(struct node));
newnode -> data = val;

if (head == NULL) {
head = newnode;
newnode -> next = head;
} else {
temp = head;
while (temp -> next != head)
temp = temp -> next;

temp -> next = newnode;
newnode -> next = head;
}
}
}

// Traverse
void display() {
struct node * temp;

printf("Contents of linked list are:\n");

if (head == NULL)
return;

temp = head;
do {
printf(" %d", temp -> data);
temp = temp -> next;
} while (temp != head);

printf("\n");
}

// Insert at position
void insert_pos(int pos, int val) {
struct node * temp, * newnode;
int i;

if (pos <= 0) {
printf("Invalid position!\n");
return;
}

if (head == NULL && pos != 1) {
printf("List is empty!\n");
return;
}

newnode = (struct node * ) malloc(sizeof(struct node));
newnode -> data = val;

if (pos == 1) {
if (head == NULL) {
head = newnode;
newnode -> next = head;
} else {
temp = head;
while (temp -> next != head)
temp = temp -> next;

newnode -> next = head;
temp -> next = newnode;
head = newnode;
}
printf("%d is inserted\n", val);
return;
}

temp = head;
for (i = 1; i < pos - 1; i++) {
temp = temp -> next;
if (temp == head) {
printf("Insufficient nodes, %d not inserted.\n", val);
free(newnode);
return;
}
}

newnode -> next = temp -> next;
temp -> next = newnode;
printf("Inserted at position %d!\n", pos);
}

// Delete at position
void delete_pos(int pos) {
struct node * temp, * prev;
int i;

if (pos <= 0) {
printf("Invalid position!\n");
return;
}

if (head == NULL) {
printf("List is empty!\n");
return;
}

temp = head;

if (pos == 1) {
if (head -> next == head) {
printf("%d deleted.\n", head -> data);
free(head);
head = NULL;
return;
}

while (temp -> next != head)
temp = temp -> next;

prev = head;
temp -> next = head -> next;
head = head -> next;

printf("%d deleted.\n", prev -> data);
free(prev);
return;
}

prev = head;
temp = head -> next;

for (i = 2; i < pos; i++) {
prev = temp;
temp = temp -> next;

if (temp == head) {
printf("Insufficient nodes\n");
return;
}
}

prev -> next = temp -> next;
printf("%d deleted.\n", temp -> data);
free(temp);
}

int main() {
int pos, val;

create();
display();

printf("Enter position to insert: ");
scanf("%d", & pos);
printf("Enter value: ");
scanf("%d", & val);

insert_pos(pos, val);
display();

printf("Enter position to be deleted: ");
scanf("%d", & pos);

delete_pos(pos);
display();

return 0;
}

