node->n = 0;
for (int i = 0; i < 2*T; i++)
node->child[i] = NULL;

return node;
}

/* ---------- Traverse ---------- */
void traverse(struct BTreeNode *root) {
if (root == NULL) return;

int i;
for (i = 0; i < root->n; i++) {
if (!root->leaf)
traverse(root->child[i]);
printf("%d ", root->keys[i]);
}
if (!root->leaf)
traverse(root->child[i]);
}

/* ---------- Split Child ---------- */
void splitChild(struct BTreeNode *parent, int i,
struct BTreeNode *y) {

struct BTreeNode *z = createNode(y->leaf);
z->n = T - 1;   // = 1 key

// Copy last (T-1) keys to new node
for (int j = 0; j < T - 1; j++)
z->keys[j] = y->keys[j + T];

// Copy children if not leaf
if (!y->leaf) {
for (int j = 0; j < T; j++)
z->child[j] = y->child[j + T];
}

y->n = T - 1;

// Shift parent's children
for (int j = parent->n; j >= i + 1; j--)
parent->child[j + 1] = parent->child[j];

parent->child[i + 1] = z;

// Shift parent's keys
for (int j = parent->n - 1; j >= i; j--)
parent->keys[j + 1] = parent->keys[j];

parent->keys[i] = y->keys[T - 1];
parent->n++;
}

/* ---------- Insert Non-Full ---------- */
void insertNonFull(struct BTreeNode *node, int k) {
int i = node->n - 1;

if (node->leaf) {
while (i >= 0 && node->keys[i] > k) {
node->keys[i + 1] = node->keys[i];
i--;
}
node->keys[i + 1] = k;
node->n++;
} else {
while (i >= 0 && node->keys[i] > k)
i--;

if (node->child[i + 1]->n == 2*T - 1) {
splitChild(node, i + 1, node->child[i + 1]);

if (k > node->keys[i + 1])
i++;
}
insertNonFull(node->child[i + 1], k);
}
}

