node->next = NULL;
for (int i = 0; i < ORDER; i++) node->children[i] = NULL;
return node;
}

/* ---------- Find Leaf ---------- */
BPTreeNode* findLeaf(BPTreeNode *cur, int key) {
if (cur == NULL) return NULL;

while (!cur->isLeaf) {
int i = 0;
while (i < cur->nKeys && key >= cur->keys[i]) i++;
cur = cur->children[i];
}
return cur;
}

/* ---------- Insert in Leaf (sorted) ---------- */
void insertInLeaf(BPTreeNode *leaf, int key) {
int i = leaf->nKeys - 1;
while (i >= 0 && leaf->keys[i] > key) {
leaf->keys[i + 1] = leaf->keys[i];
i--;
}
leaf->keys[i + 1] = key;
leaf->nKeys++;
}

/* ---------- Insert in Internal Node ---------- */
void insertInInternal(BPTreeNode *parent, int key, BPTreeNode *rightChild) {
int i = parent->nKeys - 1;

while (i >= 0 && parent->keys[i] > key) {
parent->keys[i + 1] = parent->keys[i];
parent->children[i + 2] = parent->children[i + 1];
i--;
}
parent->keys[i + 1] = key;
parent->children[i + 2] = rightChild;
parent->nKeys++;
}

/* ---------- Find Parent (simple DFS) ---------- */
BPTreeNode* findParent(BPTreeNode *cur, BPTreeNode *child) {
if (cur == NULL || cur->isLeaf) return NULL;

for (int i = 0; i <= cur->nKeys; i++) {
if (cur->children[i] == child) return cur;

BPTreeNode *p = findParent(cur->children[i], child);
if (p != NULL) return p;
}
return NULL;
}

/* ---------- Split Leaf ---------- */
void splitLeaf(BPTreeNode *leaf) {
int temp[MAX_KEYS + 1];  // 4 keys possible during overflow
for (int i = 0; i < MAX_KEYS; i++) temp[i] = leaf->keys[i];

// leaf already has one extra inserted key at the end in our flow
temp[MAX_KEYS] = leaf->keys[MAX_KEYS];

int split = (MAX_KEYS + 1) / 2; // 2

BPTreeNode *newLeaf = createNode(1);

leaf->nKeys = 0;
for (int i = 0; i < split; i++) {
leaf->keys[i] = temp[i];
leaf->nKeys++;
}

for (int i = split; i < MAX_KEYS + 1; i++) {
newLeaf->keys[newLeaf->nKeys++] = temp[i];
}

newLeaf->next = leaf->next;
leaf->next = newLeaf;

int promoteKey = newLeaf->keys[0];

if (leaf == root) {
BPTreeNode *newRoot = createNode(0);
newRoot->keys[0] = promoteKey;
newRoot->children[0] = leaf;
newRoot->children[1] = newLeaf;
newRoot->nKeys = 1;
root = newRoot;
return;
}

BPTreeNode *parent = findParent(root, leaf);
insertInInternal(parent, promoteKey, newLeaf);

// Split parent if overflow
if (parent->nKeys > MAX_KEYS) {
// handled in splitInternal
}
}

/* ---------- Split Internal Node ---------- */
void splitInternal(BPTreeNode *node) {
int mid = node->nKeys / 2;  // for 4 keys -> mid = 2

BPTreeNode *newInternal = createNode(0);

int promoteKey = node->keys[mid];

// newInternal gets keys after mid
int j = 0;
for (int i = mid + 1; i < node->nKeys; i++) {
newInternal->keys[j++] = node->keys[i];
}
newInternal->nKeys = j;

// children redistribution
j = 0;
for (int i = mid + 1; i <= node->nKeys; i++) {
newInternal->children[j++] = node->children[i];
}

// reduce old node
node->nKeys = mid;

if (node == root) {
BPTreeNode *newRoot = createNode(0);
newRoot->keys[0] = promoteKey;
newRoot->children[0] = node;
newRoot->children[1] = newInternal;
newRoot->nKeys = 1;
root = newRoot;
