/* ---------- Red-Black Tree Node ---------- */
typedef struct node {
int data;
int color;              // 0 = Black, 1 = Red
struct node *left;
struct node *right;
struct node *parent;
} RBNode;

RBNode *root = NULL;

/* ---------- Create New Node ---------- */
RBNode* createNode(int data) {
RBNode *node = (RBNode*)malloc(sizeof(RBNode));
node->data = data;
node->color = 1; // New node is RED
node->left = node->right = node->parent = NULL;
return node;
}

/* ---------- Left Rotate ---------- */
void leftRotate(RBNode *x) {
RBNode *y = x->right;
x->right = y->left;

if (y->left != NULL)
y->left->parent = x;

y->parent = x->parent;

if (x->parent == NULL)
root = y;
else if (x == x->parent->left)
x->parent->left = y;
else
x->parent->right = y;

y->left = x;
x->parent = y;
}

/* ---------- Right Rotate ---------- */
void rightRotate(RBNode *y) {
RBNode *x = y->left;
y->left = x->right;

if (x->right != NULL)
x->right->parent = y;

x->parent = y->parent;

if (y->parent == NULL)
root = x;
else if (y == y->parent->left)
y->parent->left = x;
else
y->parent->right = x;

x->right = y;
y->parent = x;
}

/* ---------- Fix Red-Black Violations ---------- */
void fixViolation(RBNode *z) {
while (z != root && z->parent->color == 1) {

// Parent is left child
if (z->parent == z->parent->parent->left) {
RBNode *y = z->parent->parent->right; // Uncle

// Case 1: Uncle is RED
if (y != NULL && y->color == 1) {
z->parent->color = 0;
y->color = 0;
z->parent->parent->color = 1;
z = z->parent->parent;
}
// Case 2 & 3
else {
if (z == z->parent->right) {
z = z->parent;
leftRotate(z);
}
z->parent->color = 0;
z->parent->parent->color = 1;
rightRotate(z->parent->parent);
}
}
// Parent is right child
else {
RBNode *y = z->parent->parent->left; // Uncle

if (y != NULL && y->color == 1) {
z->parent->color = 0;
y->color = 0;
z->parent->parent->color = 1;
z = z->parent->parent;
}
else {
if (z == z->parent->left) {
z = z->parent;
rightRotate(z);
}
z->parent->color = 0;
z->parent->parent->color = 1;
leftRotate(z->parent->parent);
}
}
}
root->color = 0; // Root is always BLACK
}

/* ---------- Insert Node ---------- */
void insert(int data) {
RBNode *z = createNode(data);
RBNode *y = NULL;
RBNode *x = root;

// BST Insert
while (x != NULL) {
y = x;
if (z->data < x->data)
x = x->left;
else
x = x->right;
}

z->parent = y;

if (y == NULL)
root = z;
else if (z->data < y->data)
y->left = z;
else
y->right = z;

fixViolation(z);
}

/* ---------- Inorder Traversal ---------- */
void inorder(RBNode *root) {
if (root != NULL) {
inorder(root->left);
printf("%d(%s) ", root->data,
root->color ? "R" : "B");
inorder(root->right);
}
}

