scanf("%d", &n);

printf("Enter elements:\n");
for (int i = 0; i < n; i++) {
scanf("%d", &x);
insert(x);
}

printf("\nInorder Traversal of Red-Black Tree:\n");
inorder(root);

return 0;
}

